}

static ssize_t qemu_send_packet_async_with_flags(NetClientState *sender, /* <=== qemu_send_packet_async_with_flags */ 
                                                 unsigned flags,
                                                 const uint8_t *buf, int size,
                                                 NetPacketSent *sent_cb)
{
    NetQueue *queue;
    int ret;

#ifdef DEBUG_NET
    printf("qemu_send_packet_async:\n");
    qemu_hexdump((const char *)buf, stdout, "net", size);
#endif

    if (sender->link_down || !sender->peer) {
        return size;
    }

    /* Let filters handle the packet first */
    ret = filter_receive(sender, NET_FILTER_DIRECTION_TX,
                         sender, flags, buf, size, sent_cb);
    if (ret) {
        return ret;
    }

    ret = filter_receive(sender->peer, NET_FILTER_DIRECTION_RX,
                         sender, flags, buf, size, sent_cb);
    if (ret) {
        return ret;
    }

    queue = sender->peer->incoming_queue;

    return qemu_net_queue_send(queue, sender, flags, buf, size, sent_cb);
}

static void mcf_fec_write_bd(mcf_fec_bd *bd, uint32_t addr) /* <=== mcf_fec_write_bd */ 
{
    mcf_fec_bd tmp;
    tmp.flags = cpu_to_be16(bd->flags);
    tmp.length = cpu_to_be16(bd->length);
    tmp.data = cpu_to_be32(bd->data);
    cpu_physical_memory_write(addr, &tmp, sizeof(tmp));
}

static inline void cpu_physical_memory_read(hwaddr addr, /* <=== cpu_physical_memory_read */ 
                                            void *buf, int len)
{
    cpu_physical_memory_rw(addr, buf, len, 0);
}

static void mcf_fec_read_bd(mcf_fec_bd *bd, uint32_t addr) /* <=== mcf_fec_read_bd */ 
{
    cpu_physical_memory_read(addr, bd, sizeof(*bd));
    be16_to_cpus(&bd->flags);
    be16_to_cpus(&bd->length);
    be32_to_cpus(&bd->data);
}

